	private static SailRepository open(Path storeDirectory) {
		SailRepository repository = new SailRepository(
				new LmdbStore(storeDirectory.toFile(), new LmdbStoreConfig("spoc,posc,ospc")));
		repository.init();
		return repository;
	}

	private static Properties snapshot(RepositoryConnection connection) throws Exception {
		List<String> all = statementLines(connection, true);
		List<String> explicit = statementLines(connection, false);
		TreeMap<String, Integer> inferredRows = new TreeMap<>();
		for (String line : all) {
			inferredRows.merge(line, 1, Integer::sum);
		}
		for (String line : explicit) {
			inferredRows.computeIfPresent(line, (ignored, count) -> count == 1 ? null : count - 1);
		}
		List<String> inferredOnly = new ArrayList<>();
		inferredRows.forEach((line, count) -> {
			for (int i = 0; i < count; i++) {
				inferredOnly.add(line);
			}
		});
		List<String> namespaces = new ArrayList<>();
		try (RepositoryResult<org.eclipse.rdf4j.model.Namespace> result = connection.getNamespaces()) {
			while (result.hasNext()) {
				var namespace = result.next();
				namespaces.add(namespace.getPrefix() + "\u0000" + namespace.getName());
			}
		}
		Collections.sort(namespaces);
		Properties manifest = new Properties();
		putDigest(manifest, "all", all);
		putDigest(manifest, "explicit", explicit);
		putDigest(manifest, "inferredOnly", inferredOnly);
		putDigest(manifest, "namespaces", namespaces);
		return manifest;
	}

	private static List<String> statementLines(RepositoryConnection connection, boolean includeInferred)
			throws Exception {
		List<String> lines = new ArrayList<>();
		try (RepositoryResult<Statement> statements = connection.getStatements(null, null, null, includeInferred)) {
			while (statements.hasNext()) {
				Statement statement = statements.next();
				lines.add(NTriplesUtil.toNTriplesString(statement.getSubject()) + "\u0000"
						+ NTriplesUtil.toNTriplesString(statement.getPredicate()) + "\u0000"
						+ NTriplesUtil.toNTriplesString(statement.getObject()) + "\u0000"
						+ (statement.getContext() == null ? "DEFAULT"
								: NTriplesUtil.toNTriplesString(statement.getContext())));
			}
		}
		Collections.sort(lines);
		return lines;
	}

	private static void assertFilteredQueries(RepositoryConnection connection) throws Exception {
		List<Statement> statements = new ArrayList<>();
		try (RepositoryResult<Statement> result = connection.getStatements(null, null, null, true)) {
			while (result.hasNext()) {
				statements.add(result.next());
			}
		}
		assertThat(statements).isNotEmpty();
		Statement sample = statements.get(0);
		assertFilterCount(connection, statements, sample.getSubject(), null, null);
		assertFilterCount(connection, statements, null, sample.getPredicate(), null);
		assertFilterCount(connection, statements, null, null, sample.getObject());
		assertFilterCount(connection, statements, sample.getSubject(), sample.getPredicate(), sample.getObject());
		assertThat(connection.hasStatement(sample.getSubject(), sample.getPredicate(), sample.getObject(), true))
				.isTrue();
	}

	private static void assertFilterCount(RepositoryConnection connection, List<Statement> all,
			org.eclipse.rdf4j.model.Resource subject, org.eclipse.rdf4j.model.IRI predicate,
			org.eclipse.rdf4j.model.Value object) throws Exception {
		long expected = all.stream()
				.filter(statement -> subject == null || subject.equals(statement.getSubject()))
				.filter(statement -> predicate == null || predicate.equals(statement.getPredicate()))
				.filter(statement -> object == null || object.equals(statement.getObject()))
				.count();
		long actual = 0;
		try (RepositoryResult<Statement> result = connection.getStatements(subject, predicate, object, true)) {
			while (result.hasNext()) {
				result.next();
				actual++;
			}
		}
		assertThat(actual).as("filtered statement query count").isEqualTo(expected);
	}

	private static void putDigest(Properties manifest, String prefix, List<String> records) throws Exception {
		manifest.setProperty(prefix + ".count", Integer.toString(records.size()));
		MessageDigest digest = MessageDigest.getInstance("SHA-256");
		for (String record : records) {
			digest.update(record.getBytes(StandardCharsets.UTF_8));
			digest.update((byte) '\n');
		}
		manifest.setProperty(prefix + ".sha256", HexFormat.of().formatHex(digest.digest()));
	}

	private static Properties loadManifest(Path path) throws IOException {
		Properties manifest = new Properties();
		try (var input = Files.newInputStream(path)) {
			manifest.load(input);
		}
		return manifest;
	}

	private static void writeManifest(Path path, Properties manifest) throws IOException {
		Files.createDirectories(path.getParent());
		try (var output = Files.newOutputStream(path)) {
			manifest.store(output, "LMDB compatibility snapshot");
		}
	}

	private static void assertSnapshotEquals(Properties expected, Properties actual, String reason) {
		for (String prefix : List.of("all", "explicit", "inferredOnly", "namespaces")) {
			assertThat(actual.getProperty(prefix + ".count")).as(reason + " " + prefix + " count")
					.isEqualTo(expected.getProperty(prefix + ".count"));
			assertThat(actual.getProperty(prefix + ".sha256")).as(reason + " " + prefix + " digest")
					.isEqualTo(expected.getProperty(prefix + ".sha256"));
		}
	}

	private static void storeFormatRemainsTwo(Path storeDirectory) throws IOException {
		Properties storeProperties = new Properties();
		try (var input = Files.newInputStream(storeDirectory.resolve("store.properties"))) {
			storeProperties.load(input);
		}
		assertThat(storeProperties.getProperty("version")).isEqualTo("2");
	}

	private static void copyTree(Path source, Path destination) throws IOException {
		try (var paths = Files.walk(source)) {
			for (Path path : paths.toList()) {
				Path target = destination.resolve(source.relativize(path));
				if (Files.isDirectory(path)) {
					Files.createDirectories(target);
				} else {
					Files.copy(path, target);
				}
			}
		}
	}
